class Solution {
public:
    int shipWithinDays(vector<int>& weights, int days) {
        auto feasible = [&](int cap) {
            int d = 1, curr = 0;
            for (int w : weights) {
                if (curr + w > cap) {
                    d++;
                    curr = 0;
                }
                curr += w;
            }
            return d <= days;
        };
        int left = 0, right = 0;
        for (int w : weights) {
            left = max(left, w);
            right += w;
        }
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (feasible(mid)) right = mid;
            else left = mid + 1;
        }
        return left;
    }
};

class Solution {
    public int shipWithinDays(int[] weights, int days) {
        int left = 0, right = 0;
        for (int w : weights) {
            left = Math.max(left, w);
            right += w;
        }
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (feasible(weights, days, mid)) right = mid;
            else left = mid + 1;
        }
        return left;
    }
    private boolean feasible(int[] weights, int days, int cap) {
        int d = 1, curr = 0;
        for (int w : weights) {
            if (curr + w > cap) {
                d++;
                curr = 0;
            }
            curr += w;
        }
        return d <= days;
    }
}

var shipWithinDays = function(weights, days) {
    function feasible(cap) {
        let d = 1, curr = 0;
        for (const w of weights) {
            if (curr + w > cap) {
                d++;
                curr = 0;
            }
            curr += w;
        }
        return d <= days;
    }
    let left = Math.max(...weights);
    let right = weights.reduce((a, b) => a + b, 0);
    while (left < right) {
        const mid = Math.floor((left + right) / 2);
        if (feasible(mid)) right = mid;
        else left = mid + 1;
    }
    return left;
};
